WITH flattened_attrs AS (SELECT id, customer_id, coupon_codes, ship_to, attributes, ship_to.zip AS ship_zip, attributes['device'] AS device, EXISTS(items, i -> i.price > 100) AS has_premium_item, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts WHERE customer_id IS NULL) SELECT customer_id, COUNT(*) AS row_count, COUNT(*) AS row_count_2, COUNT(DISTINCT device) AS distinct_devices FROM flattened_attrs GROUP BY customer_id
